import 'dart:async';import 'dart:convert';import 'package:hive_flutter/hive_flutter.dart';class ScheduledMessage {  final String id;  final String chatId;  final String content;  final DateTime scheduledAt;  final DateTime createdAt;  final bool isRecurring;  final Duration? repeatInterval;  ScheduledMessage({    required this.id,    required this.chatId,    required this.content,    required this.scheduledAt,    required this.createdAt,    this.isRecurring = false,    this.repeatInterval,  });  Map<String, dynamic> toJson() => {        'id': id,        'chatId': chatId,        'content': content,        'scheduledAt': scheduledAt.toIso8601String(),        'createdAt': createdAt.toIso8601String(),        'isRecurring': isRecurring,        'repeatInterval': repeatInterval?.inMinutes,      };  factory ScheduledMessage.fromJson(Map<String, dynamic> json) =>      ScheduledMessage(        id: json['id'],        chatId: json['chatId'],        content: json['content'],        scheduledAt: DateTime.parse(json['scheduledAt']),        createdAt: DateTime.parse(json['createdAt']),        isRecurring: json['isRecurring'] ?? false,        repeatInterval: json['repeatInterval'] != null            ? Duration(minutes: json['repeatInterval'])            : null,      );}class ScheduleService {  static const String _boxName = 'scheduled_messages';  static const Duration _checkInterval = Duration(seconds: 30);  Box<String>? _box;  Timer? _checkTimer;  final _messageReadyController =      StreamController<ScheduledMessage>.broadcast();  Stream<ScheduledMessage> get onMessageReady => _messageReadyController.stream;  Future<void> initialize() async {    _box = await Hive.openBox(_boxName);    _startChecker();  }  void _startChecker() {    _checkTimer = Timer.periodic(_checkInterval, (_) => _checkScheduled());    _checkScheduled();  }  void _checkScheduled() {    final now = DateTime.now();    final box = _box;    if (box == null) return;    final keysToDelete = <String>[];    for (final key in box.keys) {      final json = box.get(key);      if (json != null) {        try {          final msg = ScheduledMessage.fromJson(jsonDecode(json));          if (msg.scheduledAt.isBefore(now) ||              msg.scheduledAt.isAtSameMomentAs(now)) {            _messageReadyController.add(msg);            if (msg.isRecurring && msg.repeatInterval != null) {              final nextScheduled = DateTime.now().add(msg.repeatInterval!);              final updatedMsg = ScheduledMessage(                id: msg.id,                chatId: msg.chatId,                content: msg.content,                scheduledAt: nextScheduled,                createdAt: msg.createdAt,                isRecurring: true,                repeatInterval: msg.repeatInterval,              );              box.put(key, jsonEncode(updatedMsg.toJson()));            } else {              keysToDelete.add(key.toString());            }          }        } catch (e) {          keysToDelete.add(key.toString());        }      }    }    for (final key in keysToDelete) {      box.delete(key);    }  }  Future<void> scheduleMessage({    required String chatId,    required String content,    required DateTime scheduledAt,    bool isRecurring = false,    Duration? repeatInterval,  }) async {    final id = '${chatId}_${DateTime.now().millisecondsSinceEpoch}';    final message = ScheduledMessage(      id: id,      chatId: chatId,      content: content,      scheduledAt: scheduledAt,      createdAt: DateTime.now(),      isRecurring: isRecurring,      repeatInterval: repeatInterval,    );    await _box?.put(id, jsonEncode(message.toJson()));  }  List<ScheduledMessage> getScheduledMessages() {    final messages = <ScheduledMessage>[];    final box = _box;    if (box == null) return messages;    for (final json in box.values) {      try {        messages.add(ScheduledMessage.fromJson(jsonDecode(json)));      } catch (_) {}    }    messages.sort((a, b) => a.scheduledAt.compareTo(b.scheduledAt));    return messages;  }  List<ScheduledMessage> getScheduledForChat(String chatId) {    return getScheduledMessages().where((m) => m.chatId == chatId).toList();  }  Future<void> cancelScheduled(String messageId) async {    await _box?.delete(messageId);  }  Future<void> cancelAllForChat(String chatId) async {    final box = _box;    if (box == null) return;    final keysToDelete = <String>[];    for (final key in box.keys) {      if (key.toString().startsWith('${chatId}_')) {        keysToDelete.add(key.toString());      }    }    for (final key in keysToDelete) {      await box.delete(key);    }  }  void dispose() {    _checkTimer?.cancel();    _messageReadyController.close();  }}